//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.vDigitalYn = "N";
scwin.vScrenID = 'ULDSTF10006.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParentValue = function() {
    //gAcptNo = frame.Provider("../").gAcptNo;
    //gMainFormCd = frame.Provider("../").gMainFormCd;
    //gFormVer = frame.Provider("../").gFormVer;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert("회사코드:"+gIsurCd);

    if (typeof(scwin.gIsurCd) == 'undefined') {
        scwin.fn_getParam();
    }
};
scwin.fn_getParam = function() {
    var pvd = scwin.fn_GetProvider();
    var Temp0 = pvd.split("&")[0];
    scwin.gIsurCd = Temp0.split("=")[1];
};
scwin.isDigitalYn = function() {
    var pvd = scwin.fn_GetProvider();
    if (pvd != undefined && pvd != null && pvd.length > 1) {
        var Temp0 = pvd.split("&")[1];
        if (Temp0 != null && Temp0 != undefined && Temp0.length > 1) {
            var digitalYn = Temp0.split("=")[1];
            if (pvd != null && digitalYn == "Y") {
                scwin.vDigitalYn = "Y";
            }
        }
    }
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?")[1];
    //alert( url);

    if (typeof(arr) != 'undefined') {
        return (arr.length >= 1 ? arr : undefined);
    } else {
        return 'undefined';
    }
};



// 화면 로딩시 디폴트 검색
scwin.fn_Search = function() {
    var url = "";
    if (scwin.vDigitalYn == "Y") {
        url = "/digital/DisclsSearch.do?method=listDigitalAllDsclAcptIsur&inputMessageId=ALLDSCLISUR_IN";
    } else {
        url = "/DisclosureSearch.do?method=listAllDsclAcptIsur&inputMessageId=ALLDSCLISUR_IN";
    }
    url += "&outputMessageId=ALLDSCLISUR_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclAcptListAll.DataID = encodeURI(url);
    dts_DsclAcptListAll.reset();
    $c.cm.ShowWin(grd_DsclAcptListAll);
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclAcptListAll.getCellData(eval(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(eval(obj), "ISUR_CD");

    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
scwin.grd_DsclAcptListAll_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R");
        /*
        var url = "/dsclproc/ULDSTF10001.gfm?"
        		+"gAcptNo="+gAcptNo
        		+"&gViewerStat=R";
        var winTitle ="공시뷰어";

        //alert(" frame.FrameID="+ frame.FrameID);
        if (frame.Provider("/top") != undefined) {			
        	//frame.Provider("/top").WinOpen("viewer"+gAcptNo,  url+"?" + frame.FrameID,winTitle, 1000, 800);
        	frame.Provider("/top").WinOpen("viewer"+gAcptNo,  url,winTitle, 1000, 800);

        } else {
        	//frame.CreateFrame("viewer"+gAcptNo,url+"?" + frame.FrameID , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);	
        	frame.CreateFrame("viewer"+gAcptNo,url+"?" + frame.FrameID+"&gAcptNo="+gAcptNo , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);	
        }
        */

    }
};
scwin.dts_DsclAcptListAll_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclAcptListAll);
};
scwin.dts_DsclAcptListAll_OnLoadCompleted = function(rowcount) {
    if (dts_DsclAcptListAll.errorMsg) {
        $c.win.alert(dts_DsclAcptListAll.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수

    }
    $c.cm.CloseWin(rowcount, grd_DsclAcptListAll);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_DsclAcptListAll, "제출보고서 목록", "", "2");
};
scwin.gform_onload = function() {
    //fn_getParam();
    scwin.isDigitalYn();
    scwin.fn_GetParentValue();

    // 가우스헤더 셋팅
    //dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
    //dts_StudyCond.reset();	

    scwin.fn_Search();
};
